from itertools import product
import re

def xor_decrypt(data, key):
    return bytes([b ^ key[i % len(key)] for i, b in enumerate(data)])

def find_flag_in_decrypted(data):
    match = re.search(rb'csaw_ctf\{.*?\}', data)
    return match.group(0).decode() if match else None

def brute_force_xor(data, key_min, key_max):
    for key_length in range(key_min, key_max + 1):
        for key in product(range(256), repeat=key_length):
            decrypted = xor_decrypt(data, key)
            flag = find_flag_in_decrypted(decrypted)
